insert into public.wrong_entries (sort, grade, week_ref, take, what_happened, verdict) values
  (0, 'F', 'Week 4', 'Sam Darnold is what he''s always been. Do not fall for it. He will break your heart by Halloween.', 'Threw for 300+ in three of the next four, made the list at #10, and I had to write a very public apology.', 'The seeing-ghosts era ended and I was still holding the flashlight.'),
  (1, 'D', 'Week 2', 'Jayden Daniels is a fun story but rookies hit the wall. Slotting him at #9 and that''s generous.', 'Never hit the wall. Climbed to #6 and looks like a franchise cornerstone.', 'Underrated the rookie. Won''t happen again. (It will happen again.)'),
  (2, 'C', 'Week 7', 'Mahomes at #1 is the safe pick and the safe pick is the right pick. Lock it in.', 'The eye test soured for a month while Lamar ran away with it.', 'Loyalty is a hell of a drug. Diagnosis: too loyal.');
