  (2024, 12, 'Nov 26, 2024', 'your favorite rapper''s favorite top 10 list', 'published', now(), null, null, '[]'::jsonb, 'One week on the throne, then gave it back.'),
  (2024, 11, 'Nov 19, 2024', 'your favorite rapper''s favorite top 10 list', 'published', now(), null, null, '[]'::jsonb, 'Business as usual in Baltimore.'),
  (2024, 10, 'Nov 12, 2024', 'your favorite rapper''s favorite top 10 list', 'published', now(), null, null, '[]'::jsonb, 'Undefeated ugly is still undefeated.'),
  (2024, 9, 'Nov 5, 2024', 'your favorite rapper''s favorite top 10 list', 'published', now(), null, null, '[]'::jsonb, 'The MVP tour makes a stop.'),
  (2024, 8, 'Oct 29, 2024', 'your favorite rapper''s favorite top 10 list', 'published', now(), null, null, '[]'::jsonb, 'Bullied a division rival on Sunday night.'),
  (2024, 7, 'Oct 22, 2024', 'your favorite rapper''s favorite top 10 list', 'published', now(), null, null, '[]'::jsonb, 'Cincinnati''s one-man rescue mission.'),
  (2024, 6, 'Oct 15, 2024', 'your favorite rapper''s favorite top 10 list', 'published', now(), null, null, '[]'::jsonb, 'Perfect passer rating, imperfect defense.'),
  (2024, 5, 'Oct 8, 2024', 'your favorite rapper''s favorite top 10 list', 'published', now(), null, null, '[]'::jsonb, 'Truck-stick tour continues.'),
  (2024, 4, 'Oct 1, 2024', 'your favorite rapper''s favorite top 10 list', 'published', now(), null, null, '[]'::jsonb, 'Mr. Irrelevant''s brief reign.'),
