  (2024, 14, 'Dec 10, 2024', 'your favorite rapper''s favorite top 10 list', 'published', now(), 'The QB Who Shall Not Be Named', 'Threw it to the other team so much they sent him a thank-you card. Three picks, one of which the defense is still laughing about.', '[{"name":"Justin Herbert","previousRank":7},{"name":"Kirk Cousins","previousRank":9},{"name":"Dak Prescott","previousRank":10}]'::jsonb, 'Bought the courthouse. Renamed it.')
