insert into public.rankings (week_id, rank, qb_id, qb_slug, name, team_code, take, movement) values ((select id from public.weeks where season = 2024 and week_number = 14), 1, (select id from public.qbs where slug = 'lamar-jackson'), 'lamar-jackson', 'Lamar Jackson', 'BAL', 'The debate is over. He didn''t just win the argument — he bought the courthouse and renamed it after himself.', '{"kind":"holds","weeks":6}'::jsonb);
insert into public.rankings (week_id, rank, qb_id, qb_slug, name, team_code, take, movement) values ((select id from public.weeks where season = 2024 and week_number = 14), 2, (select id from public.qbs where slug = 'josh-allen'), 'josh-allen', 'Josh Allen', 'BUF', 'MVP frontrunner who plays like the game owes him money. If he''d stop trying to truck-stick linebackers on 3rd-and-2 he''d be pushing #1.', '{"kind":"up","delta":1}'::jsonb);
insert into public.rankings (week_id, rank, qb_id, qb_slug, name, team_code, take, movement) values ((select id from public.weeks where season = 2024 and week_number = 14), 3, (select id from public.qbs where slug = 'patrick-mahomes'), 'patrick-mahomes', 'Patrick Mahomes', 'KC', 'Still Mahomes. Still terrifying. But the highlight reel''s been on airplane mode and the eye test doesn''t lie. Slot three, no apologies.', '{"kind":"down","delta":1}'::jsonb);
insert into public.rankings (week_id, rank, qb_id, qb_slug, name, team_code, take, movement) values ((select id from public.weeks where season = 2024 and week_number = 14), 4, (select id from public.qbs where slug = 'brock-purdy'), 'brock-purdy', 'Brock Purdy', 'SF', 'Mr. Irrelevant is now dangerously relevant. Yes I''m biased. No I won''t apologize. The tape is immaculate and so is my conscience.', '{"kind":"up","delta":2}'::jsonb);
insert into public.rankings (week_id, rank, qb_id, qb_slug, name, team_code, take, movement) values ((select id from public.weeks where season = 2024 and week_number = 14), 5, (select id from public.qbs where slug = 'joe-burrow'), 'joe-burrow', 'Joe Burrow', 'CIN', 'Carrying that roster like a piano up five flights of stairs. Give this man a defense and we''ll talk top two.', '{"kind":"same"}'::jsonb);
insert into public.rankings (week_id, rank, qb_id, qb_slug, name, team_code, take, movement) values ((select id from public.weeks where season = 2024 and week_number = 14), 6, (select id from public.qbs where slug = 'jayden-daniels'), 'jayden-daniels', 'Jayden Daniels', 'WAS', 'The rookie who skipped the rookie part. Fearless, accurate, and already living rent-free in three division rivals'' nightmares.', '{"kind":"up","delta":3}'::jsonb);
insert into public.rankings (week_id, rank, qb_id, qb_slug, name, team_code, take, movement) values ((select id from public.weeks where season = 2024 and week_number = 14), 7, (select id from public.qbs where slug = 'jared-goff'), 'jared-goff', 'Jared Goff', 'DET', 'Indoors he''s a surgeon. Outdoors he''s a coin flip. Detroit''s ceiling is real — but so is the weather in January.', '{"kind":"down","delta":2}'::jsonb);
insert into public.rankings (week_id, rank, qb_id, qb_slug, name, team_code, take, movement) values ((select id from public.weeks where season = 2024 and week_number = 14), 8, (select id from public.qbs where slug = 'jalen-hurts'), 'jalen-hurts', 'Jalen Hurts', 'PHI', 'The Tush Push is undefeated; the deep ball is playing hard to get. Wins games, loses arguments with the film.', '{"kind":"down","delta":1}'::jsonb);
insert into public.rankings (week_id, rank, qb_id, qb_slug, name, team_code, take, movement) values ((select id from public.weeks where season = 2024 and week_number = 14), 9, (select id from public.qbs where slug = 'baker-mayfield'), 'baker-mayfield', 'Baker Mayfield', 'TB', 'The redemption arc nobody ordered and everybody''s enjoying. Chip on the shoulder, ball on a rope. Respect.', '{"kind":"up","delta":1}'::jsonb);
insert into public.rankings (week_id, rank, qb_id, qb_slug, name, team_code, take, movement) values ((select id from public.weeks where season = 2024 and week_number = 14), 10, (select id from public.qbs where slug = 'sam-darnold'), 'sam-darnold', 'Sam Darnold', 'SEA', 'I know. I KNOW. But look at the numbers before you @ me. The seeing-ghosts era is officially over. Welcome back to the list.', '{"kind":"new"}'::jsonb);
